<section class="dashboard">
  <header class="dashboard__header">
    <div class="dashboard__heading">
      <h1 hlmH1>Operations dashboard</h1>
      <p hlmMuted>Mission control for the agency. Example data.</p>
    </div>
    <a hlmBtn routerLink="/recruit" class="dashboard__primary">
      <ng-icon hlmIcon name="lucideUserPlus" />
