  <div class="dashboard__stats">
    @for (stat of vm.stats(); track stat.label) {
      <app-stat-tile
        [label]="stat.label"
        [value]="stat.value"
        [hint]="stat.hint"
        [icon]="stat.icon"
      />
    }
  </div>

  <section class="dashboard__section" aria-labelledby="top-heroes-heading">
    <div class="dashboard__section-head">
      <h2 hlmH3 id="top-heroes-heading">Top heroes this cycle</h2>
      <a hlmBtn variant="outline" size="sm" routerLink="/roster">
        <ng-icon hlmIcon name="lucideUsers" />
        View all roster
      </a>
    </div>
    <div class="dashboard__heroes">
      @for (hero of vm.topHeroes(); track hero.id) {
        <app-hero-card [hero]="hero" />
      }
    </div>
  </section>

  <section class="dashboard__section" aria-labelledby="roster-heading">
    <div class="dashboard__section-head">
      <h2 hlmH3 id="roster-heading">Roster</h2>
      <span hlmBadge variant="secondary">{{ vm.heroCount() }} heroes</span>
    </div>
  </section>
</section>
